INSERT INTO comments (comment_id, video_id, name_ko, name_en, unit, text, like_count, published_at, sid, sentiment, topic, topic_ko, sentiment_ko) VALUES ('Ugxt7vuOOZp5rd4XdI94AaABAg', 'w16uoVZpKqY', '사키하네 후야', 'Sakihane Huya', 'EVERYS', '귀여운 후야님이 귀여운 그림체를 받고 귀여운곡까지 들리는데 그와중에 귀여운 통통꼬리또한 부각되니 이토록 귀여운 쇼츠가 또있을지 궁금할 정도군요. 물론 후야님은 매일매일이 귀엽긴 합니다만 이 쇼츠에선 노리고 귀여움을 뽐내기 때문에 이 말을 전하지 않을수가 없겠습니다. 귀여운 후야를 보니 대뷔때가 떠오르는군요. 대뷔때부터 귀엽다고 판단했습니다만 지금처럼 귀엽고 무해해질것이라곤 생각하지 못하였습니다. 역시 후야님은 귀여움에 대한 재능을 타고나신것 같군요. 저도 바쿠로써 후야님의 귀여움을 본받아 최대한 귀여워지도록 시도를 해보겠습니다. 감사합니다.', 205, '2026-07-28T22:22:30Z', 203, 'positive', 'visual_design', '비주얼·디자인', '긍정');
